-- Hosbah (MH-578 C10): which of the team's SSH keys are installed on which server for which unix
-- user, one row per (ssh_key_id, server_id, unix_user). status: 'installed' (sshkey.install last
-- succeeded), 'removed' (sshkey.uninstall last succeeded, or it was never installed and this row was
-- only ever a failed attempt), 'failed' (the last op did not succeed; last_error holds why). Rows go
-- with their team; ssh_key_id also cascades with its ssh_keys row.
ALTER TABLE ssh_key_installs ADD CONSTRAINT ssh_key_installs_status_check CHECK (status IN ('installed', 'removed', 'failed'));
ALTER TABLE ssh_key_installs ADD CONSTRAINT ssh_key_installs_user_check CHECK (unix_user ~ '^[a-z_][a-z0-9_-]{0,31}$');
CREATE UNIQUE INDEX ssh_key_installs_key_server_user_key ON ssh_key_installs (ssh_key_id, server_id, unix_user);
CREATE INDEX ssh_key_installs_team_idx ON ssh_key_installs (team_id);
CREATE INDEX ssh_key_installs_server_idx ON ssh_key_installs (server_id);
ALTER TABLE ssh_key_installs ADD CONSTRAINT ssh_key_installs_key_fk FOREIGN KEY (ssh_key_id, team_id) REFERENCES ssh_keys (id, team_id) ON DELETE CASCADE;
